import { jev } from "../../core/client.ts";
import { choice, noul, score } from "../../core/helpers.ts";
import type { ChoiceAnswer, NoulAnswer, ScoreAnswer } from "../../core/types.ts";

export type AgentProfile =
  | "deterministic_script"
  | "fast_agent"
  | "reasoning_agent"
  | "browser_agent"
  | "human";

export type AgentRoute = {
  profile: AgentProfile;
  effort: number;
  needsDesktopAccess: boolean;
  rationale: string;
};

export async function routeAgent(task: string, repoName: string): Promise<AgentRoute> {
  const { answers } = await jev.systemOne({ task, repository: repoName }, {
    profile: choice("Which workflow should handle `task` in `repository`?", {
      deterministic_script: "A script or existing tool answers it with no model at all",
      fast_agent: "A quick coding agent on a cheap model for localized changes like adding a feature or fixing a test",
      reasoning_agent: "A deep reasoning model for architecture or hard debugging",
      browser_agent: "Needs a browser or logged-in web applications",
      human: "Ambiguous, sensitive, or needs judgment the tools cannot make",
    }),
    ambiguity: score("How ambiguous is `task`?", [
      "Fully specified, unambiguous request",
      "Some interpretation needed but the goal is clear",
      "Open-ended; success depends on choices not stated in the request",
    ]),
    needs_desktop: noul("Does `task` require access to logged-in applications or the desktop?"),
  });
  return decideAgent(
    answers.profile as ChoiceAnswer,
    answers.ambiguity as ScoreAnswer,
    answers.needs_desktop as NoulAnswer
  );
}

export function decideAgent(profile: ChoiceAnswer, ambiguity: ScoreAnswer, needsDesktop: NoulAnswer): AgentRoute {
  const chosen = (profile.confidence < 0.5 ? "human" : profile.choice) as AgentProfile;
  return {
    profile: chosen,
    effort: Math.round(ambiguity.score * 100) / 100,
    needsDesktopAccess: needsDesktop.noul > 0.5,
    rationale: `${chosen} @ confidence ${profile.confidence.toFixed(2)}`,
  };
}

import { jev } from "../../core/client.ts";
import { choice, score } from "../../core/helpers.ts";
import type { ChoiceAnswer, ScoreAnswer } from "../../core/types.ts";

export type IntentRoute =
  | { handler: "lookup"; reason: string }
  | { handler: "llm"; context: string }
  | { handler: "human"; reason: string };

export async function routeIntent(message: string): Promise<IntentRoute> {
  const { answers } = await jev.systemOne({ message }, {
    intent: choice("What does the author of `message` want?", {
      order_status: "Where is my order, has it shipped, tracking",
      product_question: "How a product works, compatibility, specs",
      return_exchange: "Return, exchange, or replace an item",
      complaint: "Unhappy with service or product, wants a resolution",
    }),
    needs_reasoning: score("How much thought does a good answer to `message` need?", [
      "A lookup or a one-line fact",
      "A short explanation using product knowledge",
      "A judgment call with trade-offs or an unhappy customer",
    ]),
  });
  return decideIntent(answers.intent as ChoiceAnswer, answers.needs_reasoning as ScoreAnswer);
}

export function decideIntent(intent: ChoiceAnswer, needsReasoning: ScoreAnswer): IntentRoute {
  if (intent.confidence < 0.5) {
    return { handler: "human", reason: "unclear intent" };
  }
  switch (intent.choice) {
    case "order_status":
      return { handler: "lookup", reason: "database answerable" };
    case "product_question":
      return { handler: "llm", context: "PRODUCT_CONTEXT" };
    case "return_exchange":
      return { handler: "llm", context: "RETURNS_CONTEXT" };
    case "complaint":
      return needsReasoning.score > 1
        ? { handler: "human", reason: "judgment call with an unhappy customer" }
        : { handler: "llm", context: "COMPLAINT_CONTEXT" };
    default:
      return { handler: "human", reason: "no matching intent" };
  }
}

import { jev } from "../../core/client.ts";
import { choice, score } from "../../core/helpers.ts";
import type { ChoiceAnswer, ScoreAnswer } from "../../core/types.ts";

export type ModelRoute = {
  model: "fast" | "powerful";
  effort: "low" | "high";
  rationale: string;
};

export async function routeModel(task: string): Promise<ModelRoute> {
  const { answers } = await jev.systemOne({ task }, {
    model: choice("Choose the least costly model that can complete `task`.", {
      fast: "Direct lookups, extraction, localized changes",
      powerful: "Architecture, cross-file reasoning, high-stakes decisions",
    }),
    effort: score("How much reasoning effort does `task` need?", [
      "Immediate answer, single fact or mechanical change",
      "Some investigation across a few files",
      "Deep multi-step reasoning with trade-offs",
    ]),
  });
  return decideModel(answers.model as ChoiceAnswer, answers.effort as ScoreAnswer);
}

export function decideModel(model: ChoiceAnswer, effort: ScoreAnswer): ModelRoute {
  return {
    model: model.choice === "powerful" ? "powerful" : "fast",
    effort: effort.score > 1 ? "high" : "low",
    rationale: `${model.choice} @ confidence ${model.confidence.toFixed(2)}, effort score ${effort.score}`,
  };
}
